/* Local costume preference; combat selection and controller bindings stay native. */
(function(r){'use strict';if(typeof game==='undefined'||!r.ReinaCostume)return;const V=r.ReinaCostume;let selected='default';try{if(localStorage.getItem('urban-fracture-reina-costume')==='royal-uniform')selected='royal-uniform';}catch{}V.selectPlayer(f=>f.id===game.player.id&&selected==='royal-uniform');
Promise.all([r.PolishedSprites.ready,V.ready]).then(()=>{const host=document.querySelector('.hero-select');if(!host)return;const box=document.createElement('div'),label=document.createElement('label'),select=document.createElement('select');box.id='reinaCostumeChoice399';label.textContent="Reina's costume ";select.setAttribute('aria-label',"Reina's costume");for(const [value,text]of [['default','Classic dress'],['royal-uniform','Royal Uniform']]){const option=document.createElement('option');option.value=value;option.textContent=text;select.append(option);}select.value=selected;select.disabled=!V.available;label.append(select);box.append(label);host.append(box);function preview(){const cv=document.querySelector('#heroPreview-reina');if(!cv)return;const c=cv.getContext('2d'),f=r.NeonCombat.actor('reina',0,0);f.costume=selected;c.clearRect(0,0,cv.width,cv.height);c.save();c.translate(44,107);c.scale(.62,.62);V.scope(c,f,()=>r.PolishedSprites.draw(c,f,0));c.restore();}select.onchange=()=>{selected=select.value;try{localStorage.setItem('urban-fracture-reina-costume',selected);}catch{}preview();};const portrait=r.ReinaView354?.portrait;if(portrait)r.ReinaView354.portrait=function(c,x,y,size){if(!V.portrait(c,game.player,x,y,size))return portrait(c,x,y,size);};preview();});
})(globalThis);
